const enemies={warden:{name:'별을 잃은 파수꾼',desc:'봉인의 균열에 잠식된 신전의 수호자',hp:22,maxHp:22,atk:5,def:1,xp:10,gold:6}};
let toastTimer;
function dice(){return Math.floor(Math.random()*6)+1;}
function addItem(id,count=1){let item=state.inventory.find(x=>x.id===id);if(!item){item={id,name:'작은 회복약',icon:'⚗',count:0};state.inventory.push(item);}item.count+=count;}
function removeItem(id){const item=state.inventory.find(x=>x.id===id);if(!item||item.count<1)return false;item.count--;state.inventory=state.inventory.filter(x=>x.count>0);return true;}
function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500);}
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));$('continue-button').classList.remove('hidden');}catch(e){}}
function load(){try{const data=JSON.parse(localStorage.getItem(SAVE_KEY));if(data&&data.scene){state={...initialState(),...data,flags:data.flags||{},inventory:data.inventory||[],log:data.log||[]};return true;}}catch(e){}return false;}
function record(title,text){state.log.push({title,text});$('journal-count').textContent=String(state.log.length);}
function go(key,message=''){if(!scenes[key])return;if(message)toast(message);state.scene=key;state.combat=null;state.day=scenes[key].day;state.location=scenes[key].location;if(!state.visited.includes(key))state.visited.push(key);record(scenes[key].title,scenes[key].text.replace(/<[^>]*>/g,'' ).slice(0,115)+'…');render();save();}
function render(){const scene=scenes[state.scene];if(!scene)return; $('location-name').textContent=state.location||scene.location;$('day-label').textContent=state.day||scene.day;$('story-kicker').textContent=scene.kicker;$('story-title').textContent=scene.title;$('story-text').innerHTML=scene.text.split('\n').map(line=>line?`<p>${line}</p>`:'<p class="paragraph-gap"></p>').join('');$('story-progress').textContent=`기록 ${String(Math.max(1,state.log.length)).padStart(2,'0')}`;$('choice-list').innerHTML='';$('dice-result').classList.add('hidden');$('combat-ui').classList.add('hidden');$('scene-art').dataset.scene=state.scene;
 scene.choices.forEach(choice=>{const btn=document.createElement('button');btn.className='choice-button';btn.innerHTML=`<span>${choice.label}</span>${choice.note?`<span class="choice-note">${choice.note}</span>`:''}`;btn.addEventListener('click',()=>{if(choice.roll){const result=dice();const box=$('dice-result');box.classList.remove('hidden');box.innerHTML=`<strong>${choice.roll} 판정 · ${result}/6</strong><br>${result>=4?'성공! 운명이 당신에게 미소 짓는다.':'아슬아슬한 실패. 하지만 여정은 계속된다.'}`;}choice.action();});$('choice-list').appendChild(btn);});
 if(state.combat)renderCombat();updateStats();updateTimeline();$('quest-title').textContent=state.quest||'별의 부름';$('quest-description').textContent=state.quest==='검은 짐승의 흔적'?'신전의 파수꾼을 물리치고 마을의 부탁을 완수하라.':'길을 잃은 여행자에게 다가온 목소리의 정체를 찾아라.';$('quest-status').textContent=state.scene.startsWith('ending_')?'완료':(state.flags.villageQuest?'추적 중':'진행 중');}
function updateStats(){const hp=Math.max(0,state.hp);$('hp-text').textContent=`${hp} / ${state.maxHp}`;$('hp-meter').style.width=`${Math.max(0,hp/state.maxHp*100)}%`;$('mp-text').textContent=`${state.mp} / ${state.maxMp}`;$('mp-meter').style.width=`${Math.max(0,state.mp/state.maxMp*100)}%`;$('atk-stat').textContent=state.atk;$('def-stat').textContent=state.def;$('exp-stat').textContent=`${state.exp} / ${state.level*12}`;$('exp-meter').style.width=`${Math.min(100,state.exp/(state.level*12)*100)}%`;$('gold-count').textContent=state.gold;$('inventory-list').innerHTML=state.inventory.length?state.inventory.map(x=>`<div class="inventory-item"><span class="item-icon">${x.icon}</span><span>${x.name}</span><span class="item-count">×${x.count}</span></div>`).join(''):'<div class="inventory-empty">아직 소지품이 없습니다</div>';}
function updateTimeline(){const items=[['경계의 숲','첫 번째 눈뜸','awakening'],['루와의 만남','작은 동료','companion'],['버드나무 마을','따뜻한 안식처','town'],['별의 신전','운명의 갈림길','ruins'],['별의 심장','이야기의 끝','shrine']];$('timeline').innerHTML=items.map(([name,desc,key])=>`<div class="timeline-item ${state.visited.includes(key)?'active':''}">${name}<small>${state.visited.includes(key)?'발견함':desc}</small></div>`).join('');}
function startCombat(enemyId,ambush=false){const base=enemies[enemyId];state.combat={...base};state.combatContext=enemyId;$('choice-list').innerHTML='';$('combat-ui').classList.remove('hidden');$('combat-ui').dataset.log=ambush?'기습에 성공했다! 선제 피해를 입힌다.':'전투가 시작됐다.';if(ambush){state.combat.hp-=4;}renderCombat();save();}
function renderCombat(){const enemy=state.combat;if(!enemy)return;$('combat-ui').classList.remove('hidden');$('combat-ui').innerHTML=`<div class="enemy-card"><div><div class="enemy-name">${enemy.name}</div><div class="enemy-desc">${enemy.desc}</div></div><div class="enemy-hp">${Math.max(0,enemy.hp)} / ${enemy.maxHp}</div><div class="enemy-meter"><i style="width:${Math.max(0,enemy.hp/enemy.maxHp*100)}%"></i></div></div><div class="combat-actions"><button class="choice-button" data-action="attack">검으로 공격 <span class="choice-note">피해 ${state.atk}+</span></button><button class="choice-button" data-action="spell" ${state.mp<4?'disabled':''}>별빛 화살 <span class="choice-note">마력 4</span></button><button class="choice-button" data-action="guard">방어 태세 <span class="choice-note">피해 감소</span></button><button class="choice-button" data-action="potion" ${!state.inventory.some(i=>i.id==='potion')?'disabled':''}>회복약 사용 <span class="choice-note">생명력 +10</span></button></div><div class="combat-log" id="combat-log">${$('combat-ui').dataset.log||'어떤 행동을 할까?'}</div>`;$('combat-ui').querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>combatTurn(b.dataset.action));}
function combatTurn(action){let e=state.combat;if(!e)return;let msg='';let guarding=false;
 if(action==='attack'){const roll=dice();const damage=Math.max(1,state.atk+Math.floor(roll/3)-e.def);e.hp-=damage;msg=`검을 휘둘렀다. <strong>${damage}</strong>의 피해! (주사위 ${roll})`;}
 if(action==='spell'){if(state.mp<4){toast('마력이 부족하다.');return;}state.mp-=4;const roll=dice();const damage=5+roll+Math.floor(state.atk/2);e.hp-=damage;msg=`별빛 화살이 파수꾼을 꿰뚫었다. <strong>${damage}</strong>의 피해! (주사위 ${roll})`;}
 if(action==='guard'){guarding=true;state.mp=Math.min(state.maxMp,state.mp+1);msg='자세를 낮추고 공격을 기다린다. 다음 피해가 크게 줄어든다. 마력 +1.';}
